export function searchPortfolio(query = "", category = "all") {
  const terms = normalizeSearchText(query).split(" ").filter(Boolean);
  return portfolioItems.filter((item) => {
    if (category !== "all" && item.category !== category) return false;
    const text = normalizeSearchText([
      item.title, item.description, categoryLabels[item.category], item.appCategory,
      appPlatformLabels[item.appPlatform], ...(categorySearchTerms[item.category] || []), ...(item.tags || []),
    ].join(" "));
    return terms.every((term) => text.includes(term));
  });
}

export function readPortfolioSearchState(search = "") {
  const params = new URLSearchParams(search);
  const category = params.get("category") || "all";
  return {
    query: (params.get("q") || "").slice(0, 200),
    category: portfolioCategories.includes(category) ? category : "all",
  };
}

export function portfolioSearchParams(state) {
  const params = new URLSearchParams();
  if (state.query.trim()) params.set("q", state.query.trim());
  if (state.category !== "all") params.set("category", state.category);
  return params;
}

function normalizeSearchText(value) {
  return value.normalize("NFKC").toLocaleLowerCase("ko").replace(/\s+/g, " ").trim();
}

export function getProjectDetailHref(project, searchParams = new URLSearchParams()) {
  const params = new URLSearchParams(searchParams);
  params.set("id", project.id);
  return `project.html?${params}`;
}

